<script setup lang="ts">
import { computed } from "vue";
import type { NotificationKind, NotificationPolicy } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
import { kinds } from "./labels";
const props=defineProps<{supportedKinds?:NotificationKind[]}>();
const visibleKinds=computed(()=>Object.fromEntries(Object.entries(kinds).filter(([kind])=>props.supportedKinds?props.supportedKinds.includes(kind as NotificationKind):!kind.startsWith("checkout_"))) as Partial<Record<NotificationKind,string>>);
const model=defineModel<NotificationPolicy>({required:true});
function addTemplate(kind:NotificationKind):void {
 if(!visibleKinds.value[kind]||model.value.templates[kind])return;
 model.value.templates[kind]={enabled:false,title:"",body:""};
}
const sizes=[{key:"retry_seconds",label:"Initial retry interval (seconds)"},{key:"max_retry_seconds",label:"Maximum retry interval (seconds)"},{key:"max_attempts",label:"Attempts per recovery cycle"},{key:"lease_seconds",label:"Delivery claim lease (seconds)"},{key:"max_message_chars",label:"Maximum message characters including title"}] as const;
</script>
<template><div class="form-grid"><label class="check-row"><input v-model="model.enabled" type="checkbox" />Enable notifications</label><label class="check-row"><input v-model="model.delivery_enabled" type="checkbox" />Allow Telegram delivery</label><label class="field"><span>New notification channel</span><select v-model="model.channel_mode" aria-label="New notification channel"><option value="inbox">Customer account inbox</option><option value="telegram">Telegram only</option><option value="both">Inbox and Telegram</option></select></label><label class="field"><span>Uncertain delivery result</span><select v-model="model.ambiguous_mode" aria-label="Uncertain delivery result"><option value="hold">Hold for staff review</option><option value="retry">Retry with duplicate-message risk</option></select></label><label class="field"><span>Retry delay policy</span><select v-model="model.backoff_mode" aria-label="Retry delay policy"><option value="fixed">Fixed</option><option value="exponential">Exponential up to the limit</option></select></label><NumField v-for="size in sizes" :key="size.key" :label="size.label" :model-value="String(model[size.key])" @update:model-value="model[size.key]=Number($event)" /><fieldset v-for="(label,key) in visibleKinds" :key="key" class="form-grid"><legend>{{label}}</legend><template v-if="model.templates[key]"><label class="check-row"><input v-model="model.templates[key].enabled" type="checkbox" />{{label}} enabled</label><label class="field"><span>Label {{label}}</span><input v-model="model.templates[key].title" required /></label><label class="field"><span>Text {{label}}</span><textarea v-model="model.templates[key].body" required rows="3" /></label></template><template v-else><p class="subtitle">No template configured. This notice is skipped until you add its content.</p><button type="button" class="btn secondary" @click="addTemplate(key)">Add {{label}} template</button></template></fieldset><p class="hint-box">Automatic templates support {id}, {amount_toman} and {status}. Subscription alerts also support {quota_gib}, {used_gib}, {remaining_gib}, {expires_at}, {renewal_price_toman}, {generation} and {threshold_code}. The staff message template is an editable default for new messages. Channels are saved per notification. Telegram delivery also requires the private connection to be enabled. Retrying an uncertain result may send a duplicate.</p></div></template>
